contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will set difficulty and bet limit, open to public, place a wager (if possible),
    // then call play and assert the general invariant described above.
    // params:
    //  wagerAmount - amount we attempt to wager (must equal bet limit for wager to succeed)
    //  newBetLimit - value to set as bet limit
    //  sendForWager - Ether forwarded to wager (must be >= wagerAmount)
    function run(uint256 newBetLimit, uint256 wagerAmount, uint256 sendForWager) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendForWager)); require(sendForWager <= 1000000000000000000000000000000);
        // ensure test contract has funds to send for wager
        require(address(this).balance >= sendForWager, "insufficient balance to fund wager");

        // this test contract is the owner of c (it deployed c), so it can configure it
        c.AdjustBetAmounts(newBetLimit); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(3); if (__ESBMC_reverted()) return; // set some difficulty > 1 to avoid modulo by zero
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        // record before balances and player status
        bool beforePlayer = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = address(c).balance;

        // attempt to place a wager with provided funds (may revert)
        bool wagerReverted;
        c.wager{value: sendForWager}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // after attempting wager, record whether we are a player and contract balance
        bool afterPlaced = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        // Now attempt to call play() and observe whether it reverts
        bool playReverted;
        c.play(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        // Observables after play attempt
        bool afterPlayer = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        uint256 finalBalance = address(c).balance;

        // General rule to assert for all inputs:
        // If play() did not revert, then either we are no longer recorded as a player
        // OR the contract's balance strictly decreased (indicating a payout or whale transfer).
        assert(playReverted || (!playReverted && (afterPlayer == false || finalBalance < afterBalance)));
    }

    // receive so this test contract can hold and forward ETH
    receive() external payable {}
}

