pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newBetLimit, uint256 wagerAmount, uint256 sendForWager) internal {
        sendForWager = bound(sendForWager, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendForWager);
        try c.AdjustBetAmounts(newBetLimit) {} catch { return; }
        try c.AdjustDifficulty(3) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        bool beforePlayer;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { beforePlayer = __r; } catch { return; }
        uint256 beforeBalance = address(c).balance;
        bool wagerReverted;
        try c.wager{value: sendForWager}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool afterPlaced;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterPlaced = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        bool afterPlayer;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { afterPlayer = __r; } catch { return; }
        uint256 finalBalance = address(c).balance;
        assertTrue(playReverted || (!playReverted && (afterPlayer == false || finalBalance < afterBalance)));
    }

    function testFuzz_run(uint256 newBetLimit, uint256 wagerAmount, uint256 sendForWager) public {
        _run(newBetLimit, wagerAmount, sendForWager);
    }

    receive() external payable {}
}
